"""Policy document: validation and normalisation. Mirrors packages/gate-node/src/policy.ts."""

from __future__ import annotations

import math
import re
from typing import Any

Policy = dict[str, Any]

DEFAULT_REFUSAL = "This request cannot be processed because it conflicts with the usage policy of this assistant."
DEFAULT_LABEL = "Generated by AI. Review before use."
EPOCH_ISO = "1970-01-01T00:00:00.000Z"

# Built-in patterns for Qatar identifiers; used for log masking when a policy carries no patterns of its own.
BUILT_IN_PATTERNS: list[dict[str, str]] = [
    {"name": "QID", "regex": r"\b[23]\d{10}\b", "replace": "[QID masked]"},
    {"name": "IBAN", "regex": r"\bQA\d{2}[A-Z]{4}[A-Z0-9]{21}\b", "replace": "[IBAN masked]"},
    {"name": "Phone", "regex": r"\+974[ -]?\d{4}[ -]?\d{4}\b", "replace": "[Phone masked]"},
    {"name": "Email", "regex": r"\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b", "replace": "[Email masked]"},
]


class PolicyError(ValueError):
    """The policy document cannot be enforced safely."""


def compile_pattern(regex: str) -> re.Pattern[str]:
    """ASCII mode, so \\b and \\d mean what they mean in the Node gate."""
    return re.compile(regex, re.ASCII)


def _dict(value: Any) -> dict[str, Any]:
    return value if isinstance(value, dict) else {}


def _strings(value: Any) -> list[str]:
    return [x for x in value if isinstance(x, str)] if isinstance(value, list) else []


def _days(value: Any) -> int | float | None:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    return value if math.isfinite(value) and value >= 0 else None


def normalise_policy(raw: Any, asset_id: str) -> Policy:
    """Validates a policy and fills every absent section with its "off" value.

    Raises PolicyError on anything that cannot be enforced safely.
    """
    if not isinstance(raw, dict):
        raise PolicyError("policy must be an object")
    version = raw.get("version")
    if isinstance(version, bool) or not isinstance(version, int) or version < 0:
        raise PolicyError("policy.version must be a non-negative integer")
    if "assetId" in raw and raw["assetId"] != asset_id:
        raise PolicyError(f"policy.assetId is not {asset_id}")

    masking = _dict(raw.get("masking"))
    patterns: list[dict[str, str]] = []
    raw_patterns = masking.get("patterns")
    for i, item in enumerate(raw_patterns if isinstance(raw_patterns, list) else []):
        entry = _dict(item)
        regex, replace = entry.get("regex"), entry.get("replace")
        if not isinstance(regex, str) or not isinstance(replace, str):
            raise PolicyError(f"masking.patterns[{i}] needs regex and replace")
        try:
            compile_pattern(regex)
        except re.error as error:
            raise PolicyError(f"masking.patterns[{i}].regex does not compile") from error
        name = entry.get("name")
        patterns.append({"name": name if isinstance(name, str) else f"pattern-{i}", "regex": regex, "replace": replace})

    input_section = _dict(raw.get("input"))
    denied_topics: list[dict[str, Any]] = []
    raw_topics = input_section.get("deniedTopics")
    for i, item in enumerate(raw_topics if isinstance(raw_topics, list) else []):
        entry = _dict(item)
        name = entry.get("name")
        denied_topics.append(
            {"name": name if isinstance(name, str) else f"topic-{i}", "phrases": _strings(entry.get("phrases"))}
        )

    ai_label = _dict(raw.get("aiLabel"))
    roles = _dict(raw.get("roles"))
    retention = _dict(raw.get("retention"))
    refusal = input_section.get("refusal")
    label_text = ai_label.get("text")
    issued_at = raw.get("issuedAt")

    return {
        "version": version,
        "issuedAt": issued_at if isinstance(issued_at, str) else EPOCH_ISO,
        "assetId": asset_id,
        "masking": {
            "enabled": masking.get("enabled") is True,
            "patterns": patterns,
            "unmaskedRoles": _strings(masking.get("unmaskedRoles")),
        },
        "input": {
            "refuseInjection": input_section.get("refuseInjection") is True,
            "deniedTopics": denied_topics,
            "refusal": refusal if isinstance(refusal, str) and refusal else DEFAULT_REFUSAL,
        },
        "aiLabel": {
            "enabled": ai_label.get("enabled") is True,
            "text": label_text if isinstance(label_text, str) and label_text else DEFAULT_LABEL,
        },
        "roles": {
            "enforce": roles.get("enforce") is True,
            "map": {prefix: _strings(allowed) for prefix, allowed in _dict(roles.get("map")).items()},
        },
        "retention": {
            "conversationsDays": _days(retention.get("conversationsDays")),
            "logsDays": _days(retention.get("logsDays")),
        },
        "logging": {"maskPersonalData": _dict(raw.get("logging")).get("maskPersonalData") is True},
        "telemetry": {"enabled": _dict(raw.get("telemetry")).get("enabled") is True},
    }
